def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product that can be obtained by inserting K multiplication signs into the number string.

    :param num_str: A string representing the number string.
    :param N: An integer representing the length of the number string.
    :param K: An integer representing the number of multiplication signs to insert.
    :return: The maximum product that can be obtained.
    """
    from functools import lru_cache

    @lru_cache(None)
    def dp(start, k):
        if k == 0:
            return int(num_str[start:])
        max_prod = 0
        for i in range(start + 1, N - (k - 1)):
            left = int(num_str[start:i])
            right = dp(i, k - 1)
            max_prod = max(max_prod, left * right)
        return max_prod

    return dp(0, K)

