def max_energy(beads):
    n = len(beads)
    beads = beads + beads  # Duplicate the list to handle circular nature
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):  # length is the distance between i and j in the original list
        for i in range(n):
            j = i + length - 1
            if j >= n:
                continue
            for k in range(i, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k+1][j] + beads[i] * beads[k+1] * beads[j+1])

    return max(dp[i][i+n-1] for i in range(n))

