def count_partitions(n: int, k: int, x: int) -> int:
    # Base cases
    if k == 0:
        return 1 if n == 0 else 0
    if n < k * x:
        return 0

    # Recursive function to count partitions
    def count_recursive(n, k, x):
        if k == 1:
            return 1 if x <= n else 0
        count = 0
        for i in range(x, n // k + 1):
            count += count_recursive(n - i, k - 1, i)
        return count

    return count_recursive(n, k, x)

