def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    if last == 1:
        return 1
    count = 0
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)
    memo[last] = count + 1  # +1 to include the sequence consisting of `last` itself
    return memo[last]

