def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    # Create a hashmap to store value -> index pairs for quick lookup in inorder
    index_map = {value: index for index, value in enumerate(inorder)}

    # Recursive helper function to build the tree
    def helper(in_start, in_end, post_start, post_end):
        if in_start > in_end or post_start > post_end:
            return ""

        # The last element in postorder list is the root
        root_val = postorder[post_end]
        root_index = index_map[root_val]

        # Calculate the number of nodes in the left subtree
        left_tree_size = root_index - in_start

        # Recursively build the left, right subtrees and construct preorder
        left_preorder = helper(in_start, root_index - 1, post_start, post_start + left_tree_size - 1)
        right_preorder = helper(root_index + 1, in_end, post_start + left_tree_size, post_end - 1)

        return root_val + left_preorder + right_preorder

    # Build the tree using the helper function and return preorder traversal
    return helper(0, len(inorder) - 1, 0, len(postorder) - 1)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            continue

        for src, tgt in rules:
            index = 0
            while src in current[index:]:
                index = current.index(src, index)
                new_string = current[:index] + tgt + current[index+len(src):]

                if new_string == B:
                    return steps + 1

                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, steps + 1))

                index += 1

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    Args:
    num (int): The integer to check for primality.

    Returns:
    bool: True if `num` is a prime number, False otherwise.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

