            if heights[i] > heights[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Calculate the Longest Decreasing Subsequence (LDS) starting at each position
    lds = [1] * n
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Find the maximum length of the choir formation
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, lis[i] + lds[i] - 1)

    # The minimum number of students to leave is the total number of students minus the maximum choir length
    return n - max_choir_length

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Left to right, calculate the longest increasing subsequence ending at each position
    left_increasing = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                left_increasing[i] = max(left_increasing[i], left_increasing[j] + 1)

    # Right to left, calculate the longest decreasing subsequence starting at each position
    right_decreasing = [1] * n
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j]:
                right_decreasing[i] = max(right_decreasing[i], right_decreasing[j] + 1)

    # Calculate the maximum length of the choir formation
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, left_increasing[i] + right_decreasing[i] - 1)

    # The minimum number of students to leave is the total number of students minus the maximum choir length
    return n - max_choir_length

def hanoi_double_iterative(n: int) -> int:
    if n == 0:
        return 0
    moves = 0
    current_moves = 2  # Base case for n=1
    for i in range(n):
        moves += current_moves
        current_moves = 3 * current_moves + 2  # Recursive relation
    return moves

def hanoi_double_iterative(n: int) -> int:
    if n == 0:
        return 0
    moves = 2
    for i in range(2, n + 1):
        moves = 3 * moves + 2
    return moves

def hanoi_double_iterative(n: int) -> int:
    if n == 0:
        return 0
    moves = 2  # Base case for n=1
    for i in range(2, n + 1):
        moves = 3 * moves - 2
    return moves
